import openpyxl
from openpyxl.utils import get_column_letter

wb=openpyxl.load_workbook('gdp.xlsx')
ws=wb['Task']

lookup_formula = "=IFERROR(INDEX(Data!$H$21:$L$40, MATCH($D{row}, Data!$B$21:$B$40, 0), MATCH({col}$9, Data!$H$4:$L$4, 0)),\"\")"

for start_row, end_row in [(12,17),(19,24),(26,31)]:
    for r in range(start_row, end_row+1):
        for c in range(8,13):
            col_letter = get_column_letter(c)
            ws.cell(row=r, column=c).value = lookup_formula.format(row=r, col=col_letter)

for r in range(35, 41):
    for c in range(8,13):
        col_letter = get_column_letter(c)
        exports_row = r - 23
        imports_row = r - 16
        gdp_row = r - 9
        formula = f"=IFERROR(({col_letter}{exports_row}-{col_letter}{imports_row})/{col_letter}{gdp_row},\"\")"
        ws.cell(row=r, column=c).value = formula

stats_templates = {
    42: "=IF(COUNT({col}35:{col}40)=0,\"\",MIN({col}35:{col}40))",
    43: "=IF(COUNT({col}35:{col}40)=0,\"\",MAX({col}35:{col}40))",
    44: "=IF(COUNT({col}35:{col}40)=0,\"\",MEDIAN({col}35:{col}40))",
    45: "=IF(COUNT({col}35:{col}40)=0,\"\",AVERAGE({col}35:{col}40))",
    46: "=IF(COUNT({col}35:{col}40)=0,\"\",PERCENTILE({col}35:{col}40,0.25))",
    47: "=IF(COUNT({col}35:{col}40)=0,\"\",PERCENTILE({col}35:{col}40,0.75))",
}
for r, template in stats_templates.items():
    for c in range(8,13):
        col_letter = get_column_letter(c)
        ws.cell(row=r, column=c).value = template.format(col=col_letter)

for c in range(8,13):
    col_letter = get_column_letter(c)
    ws.cell(row=50, column=c).value = f"=IF(SUM({col_letter}26:{col_letter}31)=0,\"\",SUMPRODUCT({col_letter}35:{col_letter}40,{col_letter}26:{col_letter}31)/SUM({col_letter}26:{col_letter}31))"

wb.save('gdp.xlsx')
